// function checkAccess(role, isOnline, hasSubscription)
// Admin: "Full access"
// Online + Subscriber: "Premium access"
// Online: "Basic access"
// Offline: "No access"

solution:
function checkAccess(role, isOnline, hasSubscription) {
  if (role === "admin") return "Full access"
  if (!isOnline) return "No access"
  if (hasSubscription) return "Premium access"
  return "Basic access"
}
